func:
// Converte o texto em objeto e anota canal e tipo. Saida 1: valido; saida 2: invalido.
msg.texto = msg.payload;
let dados;
try {
    dados = JSON.parse(msg.payload);
} catch (e) {
    msg.erro = 'json_invalido';
    return [null, msg];
}
if (dados === null || typeof dados !== 'object' || Array.isArray(dados)) {
    msg.erro = 'json_nao_e_objeto';
    return [null, msg];
}
msg.canal = msg.topic.split('/').pop();
// Produto/lote em vigor no ESP32, usados nas paradas lidas por Modbus.
if (msg.canal === 'telemetria' && dados.produto) {
    global.set('contexto', { produto: dados.produto, lote_producao: dados.lote_producao,
        lote_capsula: dados.lote_capsula || null, lote_po: dados.lote_po || null });
}
msg.tipoEvento = msg.canal === 'eventos' ? String(dados.tipo || '') : '';
return [msg, null];

// Monta a chamada parametrizada; so aceita funcoes conhecidas.
const permitidas = ['gravar_telemetria', 'gravar_parada_inicio', 'gravar_parada_fim', 'gravar_boot',
    'gravar_sensor', 'gravar_config_aplicada', 'gravar_disponibilidade', 'registrar_somente'];
if (!permitidas.includes(msg.funcao)) {
    throw new Error('funcao nao permitida: ' + msg.funcao);
}
msg.query = 'SELECT integracao.' + msg.funcao + '($1, $2::jsonb) AS resultado';
msg.params = [msg.topic, msg.texto];
return msg;

// Conta os resultados devolvidos pelas funcoes e mostra no status do no.
const r = (msg.payload && msg.payload[0] && msg.payload[0].resultado) || '?';
const n = (context.get('n') || 0) + 1;
const dup = (context.get('dup') || 0) + (r === 'duplicada' ? 1 : 0);
context.set('n', n);
context.set('dup', dup);
node.status({ fill: 'green', shape: 'dot', text: n + ' gravadas (' + dup + ' duplicadas)' });
msg.payload = { topico: msg.topic, funcao: msg.funcao, resultado: r };
return msg;

// Erro na gravacao (restricao violada, campo ausente...) ou JSON invalido: guarda o texto e o motivo.
const motivo = msg.erro || (msg.error && msg.error.message) || String(msg.error || 'erro');
const n = (context.get('n') || 0) + 1;
context.set('n', n);
node.status({ fill: 'red', shape: 'ring', text: n + ' falha(s)' });
node.warn('Falha ao gravar ' + msg.topic + ': ' + motivo);
msg.query = 'SELECT integracao.registrar_falha($1, $2, $3) AS resultado';
msg.params = [msg.topic, String(msg.texto !== undefined ? msg.texto : msg.payload), motivo];
return msg;

// Monta a leitura FC03 (holding registers) do bloco que contem STATUS e FALHA.
// Desligada por padrao: MODBUS_HABILITADO=true so com o simulador ou com acesso ao CLP autorizado.
if (env.get('MODBUS_HABILITADO') !== 'true') return [null, null];
const rs = Number(env.get('MODBUS_REG_STATUS')), rf = Number(env.get('MODBUS_REG_FALHA'));
const inicio = Math.min(rs, rf), qtd = Math.abs(rs - rf) + 1;
if (!(qtd >= 1 && qtd <= 125)) { node.error('MODBUS_REG_STATUS/FALHA invalidos'); return [null, null]; }
const tid = ((context.get('tid') || 0) + 1) & 0xffff;
context.set('tid', tid);
const unit = Number(env.get('MODBUS_UNIT') || 1);
const q = Buffer.alloc(12);
q.writeUInt16BE(tid, 0); q.writeUInt16BE(0, 2); q.writeUInt16BE(6, 4); q.writeUInt8(unit, 6);
q.writeUInt8(3, 7); q.writeUInt16BE(inicio, 8); q.writeUInt16BE(qtd, 10);
msg.payload = q;
msg.host = env.get('MODBUS_HOST');
msg.port = Number(env.get('MODBUS_PORTA'));
msg.modbus = { tid, unit, inicio, qtd, rs, rf };
// Primeira leitura desta implantacao: BOOT do leitor virtual fecha paradas Modbus deixadas abertas.
let boot = null;
if (!flow.get('modbus_boot_enviado')) {
    flow.set('modbus_boot_enviado', true);
    boot = { topic: 'mixnutri/sala01/eventos', funcao: 'gravar_boot', evento: 'BOOT' };
}
return [msg, boot];

// Falha de conexao do tcp request: conta como leitura sem resposta.
msg.erroModbus = (msg.error && msg.error.message) || 'erro';
return msg;

// Interpreta a resposta FC03 e gera PARADA_INICIO/FIM no formato do contrato v2.
// Perda de comunicacao (3 leituras seguidas) leva a DESCONHECIDO, nunca a PARADO.
const DEV = 'clp-sala01-modbus';
const boot = flow.get('modbus_boot') || ('nr' + Date.now().toString(36));
flow.set('modbus_boot', boot);
const t0 = flow.get('modbus_t0') || Date.now();
flow.set('modbus_t0', t0);

function cabecalho(tipo) {
    const seq = (flow.get('modbus_seq') || 0);
    flow.set('modbus_seq', seq + 1);
    const ctx = global.get('contexto') || { produto: 'NAO_INFORMADO', lote_producao: 'NAO_INFORMADO' };
    return { schema_version: 2, device_id: DEV, sala_id: 'sala01', boot_id: boot, seq,
        uptime_ms: Date.now() - t0, timestamp_utc: new Date().toISOString(), clock_synced: true,
        origem_dados: env.get('MODBUS_ORIGEM_DADOS') || 'simulacao', tipo,
        produto: ctx.produto, lote_producao: ctx.lote_producao,
        lote_capsula: ctx.lote_capsula || null, lote_po: ctx.lote_po || null };
}
function enviar(funcao, p) {
    return { topic: 'mixnutri/sala01/eventos', funcao, texto: JSON.stringify(p) };
}

if (msg.evento === 'BOOT') {
    return enviar('gravar_boot', Object.assign(cabecalho('BOOT'), { reset_reason: 0, fonte_estado: 'modbus' }));
}

let status = null, falha = null;
const m = msg.modbus, r = Buffer.isBuffer(msg.payload) ? msg.payload : null;
if (!msg.erroModbus && m && r && r.length >= 9 + 2 * m.qtd && r.readUInt16BE(0) === m.tid
        && r.readUInt8(7) === 3 && r.readUInt8(8) === 2 * m.qtd) {
    status = r.readUInt16BE(9 + 2 * (m.rs - m.inicio));
    falha = r.readUInt16BE(9 + 2 * (m.rf - m.inicio));
}
let novo;
if (status === null) {
    const erros = (flow.get('modbus_erros') || 0) + 1;
    flow.set('modbus_erros', erros);
    node.status({ fill: 'red', shape: 'ring', text: 'sem resposta (' + erros + ')' });
    if (erros < 3) return null;
    novo = 'DESCONHECIDO';
} else {
    flow.set('modbus_erros', 0);
    novo = status === 1 ? 'OPERANDO' : status === 0 ? 'PARADO' : 'DESCONHECIDO';
    node.status({ fill: novo === 'PARADO' ? 'red' : 'green', shape: 'dot', text: novo + ' falha=' + falha });
}
const antes = flow.get('modbus_estado') || 'DESCONHECIDO';
flow.set('modbus_estado', novo);
if (novo === antes) return null;

const aberta = flow.get('modbus_parada');
if (novo === 'PARADO' && !aberta) {
    const n = (flow.get('modbus_n') || 0) + 1;
    flow.set('modbus_n', n);
    const p = Object.assign(cabecalho('PARADA_INICIO'), { fonte_estado: 'modbus', de: antes, para: novo,
        evento_id: DEV + '-' + boot + '-modbus-' + n, codigo_falha: falha });
    p.inicio_uptime_ms = p.uptime_ms;
    p.inicio_utc = p.timestamp_utc;
    flow.set('modbus_parada', { evento_id: p.evento_id, inicio_uptime_ms: p.inicio_uptime_ms, inicio_utc: p.inicio_utc });
    return enviar('gravar_parada_inicio', p);
}
if (antes === 'PARADO' && aberta) {
    flow.set('modbus_parada', null);
    const p = Object.assign(cabecalho('PARADA_FIM'), aberta, { fonte_estado: 'modbus', de: antes, para: novo,
        codigo_falha: falha, motivo_fim: novo === 'OPERANDO' ? 'retorno_operacao' : 'fonte_indisponivel' });
    p.fim_uptime_ms = p.uptime_ms;
    p.fim_utc = p.timestamp_utc;
    p.duracao_ms = p.fim_uptime_ms - p.inicio_uptime_ms;
    return enviar('gravar_parada_fim', p);
}
return null;

// Guarda o valor do campo para montar a mensagem quando o botao for usado.
const campos = flow.get('campos') || {};
campos[msg.topic] = msg.payload;
flow.set('campos', campos);
return null;

// Valores de exemplo (didaticos) para testar sem a interface.
flow.set('campos', Object.assign(flow.get('campos') || {}, { ur_max: 58, histerese: 4, limiar_db: -22, banda_db: 12,
    validade_min: 1, produto: 'PRODUTO_TESTE', lote_producao: 'LOTE_TESTE_02', lote_capsula: 'CAP_TESTE' }));
return [msg, msg];

// Comando AUTO/MANUAL no contrato v2: cmd_id unico, validade e ts; nunca retido.
const c = flow.get('campos') || {};
const acao = String(msg.payload);
const agora = Date.now();
const p = { cmd_id: 'admin-' + agora, ts: Math.floor(agora / 1000) };
if (acao === 'AUTO') {
    p.modo = 'AUTO';
} else if (acao === 'MANUAL_ON' || acao === 'MANUAL_OFF') {
    const min = Number(c.validade_min || 15);
    if (!(min >= 1 && min <= 480)) {
        return [null, { payload: 'A validade do MANUAL deve ficar entre 1 e 480 min' }];
    }
    p.modo = 'MANUAL';
    p.rele = acao === 'MANUAL_ON' ? 'ON' : 'OFF';
    p.validade_s = Math.round(min * 60);
} else {
    return null;
}
return [{ topic: 'mixnutri/sala01/comandos', payload: JSON.stringify(p), retain: false, qos: 1 },
        { payload: 'Comando enviado: ' + p.cmd_id + ' ' + p.modo + (p.rele ? ' ' + p.rele : '') }];

// A versao precisa ser maior que a aplicada no ESP32: consulta o banco antes de publicar.
msg.acao = 'configuracao';
msg.query = 'SELECT integracao.proxima_versao_config($1) AS versao';
msg.params = ['sala01'];
return msg;

// Produto e lote em producao (obrigatorios produto e lote_producao, 1 a 32 caracteres).
const c = flow.get('campos') || {};
const t = (x) => (typeof x === 'string' ? x.trim() : '');
const p = { cmd_id: 'ctx-' + Date.now(), produto: t(c.produto), lote_producao: t(c.lote_producao) };
if (t(c.lote_capsula)) p.lote_capsula = t(c.lote_capsula);
if (t(c.lote_po)) p.lote_po = t(c.lote_po);
const ok = (s) => s.length >= 1 && s.length <= 32;
if (!ok(p.produto) || !ok(p.lote_producao) || [p.lote_capsula, p.lote_po].some((s) => s !== undefined && !ok(s))) {
    return [null, { payload: 'Contexto não enviado: produto e lote de produção com 1 a 32 caracteres' }];
}
return [{ topic: 'mixnutri/sala01/contexto', payload: JSON.stringify(p), retain: true, qos: 1 },
        { payload: 'Contexto enviado: ' + p.produto + ' / ' + p.lote_producao }];

msg.acao = 'estado';
msg.query = 'SELECT integracao.estado_admin($1) AS estado';
msg.params = ['sala01'];
return msg;

// Configuracao no formato do Admin do contrato v2 (ur_max, histerese, limiar_db, banda_db em dBFS).
const c = flow.get('campos') || {};
const versao = Number(msg.payload && msg.payload[0] && msg.payload[0].versao);
const v = { ur_max: Number(c.ur_max), histerese: Number(c.histerese), limiar_db: Number(c.limiar_db),
            banda_db: Number(c.banda_db) };
const erros = [];
if (!(v.ur_max > 0 && v.ur_max <= 100)) erros.push('UR máxima entre 0 e 100 %');
if (!(v.histerese > 0 && v.histerese < v.ur_max)) erros.push('histerese positiva e menor que a UR máxima');
if (!(v.limiar_db <= 0 && v.limiar_db >= -120)) erros.push('limiar entre -120 e 0 dBFS');
if (!(v.banda_db > 0 && v.limiar_db - v.banda_db >= -120)) erros.push('banda positiva (limiar - banda >= -120 dBFS)');
if (!(versao >= 1)) erros.push('versão não obtida do banco');
if (erros.length) return [null, { payload: 'Configuração não enviada: ' + erros.join('; ') }];
const p = Object.assign({ cmd_id: 'cfg-' + versao, versao }, v);
return [{ topic: 'mixnutri/sala01/configuracao', payload: JSON.stringify(p), retain: true, qos: 1 },
        { payload: 'Configuração v' + versao + ' enviada; aguarde a confirmação do ESP32' }];

// Preenche os campos e o resumo ao abrir/implantar.
const e = (msg.payload && msg.payload[0] && msg.payload[0].estado) || {};
const cfg = e.configuracao || {}, ctx = e.contexto || {};
if (ctx.produto) global.set('contexto', ctx);
const campos = Object.assign(flow.get('campos') || {}, { validade_min: 15 });
const valores = { ur_max: cfg.ur_max, histerese: cfg.histerese, limiar_db: cfg.limiar_db, banda_db: cfg.banda_db,
    produto: ctx.produto, lote_producao: ctx.lote_producao, lote_capsula: ctx.lote_capsula, lote_po: ctx.lote_po };
for (const [k, v] of Object.entries(valores)) if (v !== undefined && v !== null) campos[k] = v;
flow.set('campos', campos);
const n = (k) => (campos[k] === undefined ? null : { payload: campos[k] });
return [n('ur_max'), n('histerese'), n('limiar_db'), n('banda_db'), n('validade_min'),
        n('produto'), n('lote_producao'), n('lote_capsula'), n('lote_po'),
        { payload: cfg.versao ? 'v' + cfg.versao + ': liga ' + cfg.ur_max + ' %UR, histerese ' + cfg.histerese +
            ' pp, operando >= ' + cfg.limiar_db + ' dBFS' : 'sem configuração ativa' },
        { payload: 'aguardando a próxima telemetria' },
        { payload: e.disponibilidade ? e.disponibilidade.estado + ' (última mensagem registrada)' : 'sem registro' },
        { payload: e.ultima_confirmacao ? e.ultima_confirmacao.tipo + ' ' + e.ultima_confirmacao.cmd_id + ': ' +
            (e.ultima_confirmacao.aceito ? 'aceito' : 'RECUSADO') + ' (' + e.ultima_confirmacao.motivo + ')' : 'sem registro' }];

// Atualiza o resumo do Admin com as mensagens recebidas (mesma assinatura da ingestao).
const d = msg.dados || {};
const fmt = (x, u) => (x === null || x === undefined ? 'n/d' : x + u);
if (msg.canal === 'telemetria') {
    return [{ payload: (d.clima_valido ? fmt(d.umidade_pct, ' %UR') + ', ' + fmt(d.temperatura_c, ' °C') : 'sensor de clima em falha') +
        ' | ruido ' + fmt(d.nivel_ruido, ' ' + (d.unidade_ruido || '')) + ' (não é dB SPL)' +
        ' | máquina ' + d.estado_maquina + ' (' + d.fonte_estado + ') | ' + d.modo +
        ' | rele ' + (d.desumidificador_comandado ? 'ligado' : 'desligado') + ' (' + d.motivo_rele + ')' +
        ' | ' + d.produto + ' / ' + d.lote_producao }, null, null, null];
}
if (msg.canal === 'disponibilidade') {
    return [null, { payload: d.estado + (d.boot_id ? ' (boot ' + d.boot_id + ')' : '') }, null, null];
}
if (msg.canal === 'confirmacoes') {
    const texto = d.tipo + ' ' + d.cmd_id + ': ' + (d.aceito ? 'aceito' : 'RECUSADO') + ' (' + d.motivo + ')';
    return [null, null, { payload: texto }, d.aceito ? null : { payload: 'ESP32 recusou ' + texto }];
}
if (msg.canal === 'eventos' && d.tipo === 'CONFIG_APLICADA') {
    return [null, null, { payload: 'CONFIG_APLICADA v' + d.config_version + ': liga ' + d.ur_liga + ', desliga ' + d.ur_desliga +
        ' %UR; operando >= ' + d.limiar_operando_dbfs + ', parado <= ' + d.limiar_parado_dbfs + ' dBFS' }, null];
}
return null;

// Alerta aberto pelas funcoes SQL vira notificacao no painel (tambem fica em alertas_emitidos).
const r = msg.payload && msg.payload.resultado;
if (typeof r === 'string' && /alerta \w+ aberto/.test(r)) {
    return { payload: r.replace(/^.*?; /, '') + ' (' + msg.payload.topico + ')' };
}
return null;
